if($_SERVER['REQUEST_METHOD']==='POST'){try{$a=$_POST['accion']??'';if($a==='crear'){$id=(int)$_POST['id_instrumento'];$diag=trim((string)$_POST['diagnostico']);$costo=(float)$_POST['costo'];if(!$id||$diag===''||$costo<0)throw new InvalidArgumentException('Instrumento, diagnóstico y costo válido son obligatorios.');$s=$db->prepare('INSERT INTO reparacion(id_instrumento,id_usuario,diagnostico,estado,fecha_ingreso,costo) VALUES(?,?,?,"en_revision",?,?)');$s->execute([$id,$_SESSION['usuario']['id_usuario'],$diag,$_POST['fecha_ingreso']?:date('Y-m-d H:i:s'),$costo]);registrar_bitacora('reparacion_creada','ID '.$db->lastInsertId());}elseif($a==='estado'){$estado=(string)$_POST['estado'];if(!in_array($estado,['en_revision','en_reparacion','finalizado'],true))throw new InvalidArgumentException('Estado inválido.');$s=$db->prepare('UPDATE reparacion SET estado=? WHERE id_reparacion=?');$s->execute([$estado,(int)$_POST['id_reparacion']]);registrar_bitacora('reparacion_estado','ID '.$_POST['id_reparacion'].' '.$estado);}}catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'No se pudo guardar la reparación.';}}
$filtro=(string)($_GET['estado']??'');$where=$filtro!==''?' WHERE r.estado=?':'';$params=$filtro!==''?[$filtro]:[];$s=$db->prepare('SELECT r.*,i.codigo_qr,i.tipo,u.nombre AS tecnico FROM reparacion r INNER JOIN instrumento i ON i.id_instrumento=r.id_instrumento INNER JOIN usuario u ON u.id_usuario=r.id_usuario'.$where.' ORDER BY r.fecha_ingreso DESC');$s->execute($params);$reparaciones=$s->fetchAll();$instrumentos=$db->query('SELECT id_instrumento,codigo_qr,tipo FROM instrumento ORDER BY codigo_qr')->fetchAll();$titulo='Reparaciones';require __DIR__.'/../../includes/header.php';
